"""site/docs/index.html is generated by scripts/gen_docs.py from the real CLI, the Event schema
and scripts/docs_src/*.md. These tests keep it in sync and check the Markdown-subset renderer."""
from __future__ import annotations

import dataclasses
import html
import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "scripts"))
sys.path.insert(0, str(ROOT))

import gen_docs  # noqa: E402
from gitmotive import cli, store  # noqa: E402

PAGE = ROOT / "site" / "docs" / "index.html"


def _render(md: str) -> str:
    return gen_docs.render_md(md, gen_docs.Ids(), [])


def _text(fragment: str) -> str:
    return html.unescape(re.sub(r"<[^>]+>", "", fragment))


# --- sync ----------------------------------------------------------------------------------

def test_check_passes_on_committed_page():
    r = subprocess.run([sys.executable, str(ROOT / "scripts" / "gen_docs.py"), "--check"],
                       cwd=ROOT, capture_output=True, text=True)
    assert r.returncode == 0, f"docs are stale; run python3 scripts/gen_docs.py\n{r.stdout}{r.stderr}"


def test_check_fails_with_diff_summary_when_stale():
    import contextlib
    import io
    with tempfile.TemporaryDirectory() as d:
        out = Path(d) / "index.html"
        out.write_text(gen_docs.build().replace("Quickstart", "Quick start", 1), encoding="utf-8")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = gen_docs.check(out)
        assert rc == 1, rc
        assert "is stale" in buf.getvalue() and "Quick start" in buf.getvalue(), buf.getvalue()
        out.unlink()
        with contextlib.redirect_stdout(io.StringIO()):
            assert gen_docs.check(out) == 1, "missing page must fail"
        out.write_text(gen_docs.build(), encoding="utf-8")
        with contextlib.redirect_stdout(io.StringIO()):
            assert gen_docs.check(out) == 0


def test_bad_args_exit_2():
    r = subprocess.run([sys.executable, str(ROOT / "scripts" / "gen_docs.py"), "--nope"],
                       cwd=ROOT, capture_output=True, text=True)
    assert r.returncode == 2, r


# --- renderer ------------------------------------------------------------------------------

def test_code_block_escapes_markup():
    out = _render("```sh\necho <script>alert(1)</script> & \"q\"\n```\n")
    assert "<script>" not in out, out
    assert "&lt;script&gt;alert(1)&lt;/script&gt; &amp; &quot;q&quot;" in out, out
    assert out.startswith("<pre") and out.endswith("</code></pre>"), out
    assert 'role="region"' in out and 'tabindex="0"' in out, out


def test_inline_code_and_links():
    out = _render("Run `<run> capture` or see [the repo](https://github.com/rvasqz86/gitmotive) <b>.\n")
    assert "<code>&lt;run&gt; capture</code>" in out, out
    assert '<a href="https://github.com/rvasqz86/gitmotive">the repo</a>' in out, out
    assert "&lt;b&gt;" in out and "<b>" not in out, out
    # a link inside a code span stays literal
    assert "<a " not in _render("`[x](y)`"), _render("`[x](y)`")


def test_headings_lists_paragraphs():
    toc: list = []
    ids = gen_docs.Ids()
    out = gen_docs.render_md("# Top\n\ntext one\ncontinued\n\n## Sub\n\n- a\n- b `c`\n\n"
                             "3. three\n4. four\n\n## Sub\n", ids, toc)
    assert '<h2 id="top"><span class="hash" aria-hidden="true">#</span>Top</h2>' in out, out
    assert "<p>text one continued</p>" in out, out
    assert "<ul><li>a</li><li>b <code>c</code></li></ul>" in out, out
    assert '<ol start="3"><li>three</li><li>four</li></ol>' in out, out
    assert [(l, i) for l, i, _ in toc] == [(2, "top"), (3, "sub"), (3, "sub-2")], toc


def test_unclosed_fence_runs_to_end():
    out = _render("```\na < b\n\nstill code")
    assert "a &lt; b\n\nstill code" in out, out


# --- the generated page --------------------------------------------------------------------

def test_cli_reference_lists_every_usage_entry_verbatim():
    src = PAGE.read_text(encoding="utf-8")
    pres = [_text(m) for m in re.findall(r"<pre\b[^>]*>(.*?)</pre>", src, re.S)]
    for cmd, (usage, desc) in cli.USAGE.items():
        assert usage in pres, f"USAGE[{cmd!r}] usage line not verbatim in a code block: {usage}"
        assert desc in _text(src), f"USAGE[{cmd!r}] description missing: {desc}"
    assert "gitmotive --version | -V" in pres
    assert cli.__doc__.rstrip("\n") in pres, "help output (cli.__doc__) missing"


def test_experimental_agents_marked():
    src = PAGE.read_text(encoding="utf-8")
    for a in cli.EXPERIMENTAL:
        assert f'{a} <span class="exp">(experimental)</span>' in src, a
        assert f"<code>{a}</code>" in src, a


def test_data_format_table_matches_event_fields():
    src = PAGE.read_text(encoding="utf-8")
    table = re.search(r'<table class="agents fields">(.*?)</table>', src, re.S)
    assert table, "no data-format table"
    rows = re.findall(r"<tbody>(.*)</tbody>", table.group(1), re.S)[0]
    rows = re.findall(r"<tr>(.*?)</tr>", rows, re.S)
    names = [f.name for f in dataclasses.fields(store.Event)]
    assert len(rows) == len(names), (len(rows), names)
    for row, name in zip(rows, names):
        cells = [_text(c) for c in re.findall(r"<t[hd]\b[^>]*>(.*?)</t[hd]>", row, re.S)]
        assert cells[0] == name and cells[2] == store.FIELD_DOCS[name], (cells, name)


def test_headings_have_ids_and_toc_links_resolve():
    src = PAGE.read_text(encoding="utf-8")
    heads = re.findall(r"<h([1-6])([^>]*)>", src)
    assert heads and all('id="' in attrs for _, attrs in heads), heads
    ids = re.findall(r'\sid="([^"]+)"', src)
    assert len(ids) == len(set(ids)), "duplicate ids"
    toc = re.search(r'<nav class="toc"[^>]*>(.*?)</nav>', src, re.S)
    assert toc, "no in-page TOC"
    targets = re.findall(r'href="#([^"]+)"', toc.group(1))
    assert {"install", "quickstart", "agent-setup", "cli-reference", "data-format"} <= set(targets), targets
    assert all(t in ids for t in targets), [t for t in targets if t not in ids]


def test_hook_command_run_form_documented():
    t = _text(PAGE.read_text(encoding="utf-8"))
    for s in ("<run> capture --agent cursor --event <beforeSubmitPrompt|afterFileEdit>",
              "<run> capture --agent claude --source copilot",
              "<run> capture --agent claude --source omp",
              "<python> -I -m gitmotive", "PYTHONPATH=<pkg> <python> -m gitmotive",
              "GITMOTIVE_STORE=user", "upserts"):
        assert s in t, f"missing: {s}"


def test_docs_sources_mention_no_fake_commands():
    for p in (ROOT / "scripts" / "docs_src").glob("*.md"):
        t = p.read_text(encoding="utf-8")
        assert not re.search(r"gitmotive\s+(init|blame)\b", t), p


